set
  title = 'Orchestration / Arranging',
  goal = 'Orchestration / Arranging',
  summary = 'This course develops practical and artistic skills in writing for instruments and ensembles. Students study ranges, transpositions, instrumental color, string, woodwind, brass, and percussion writing, full-orchestra scoring, voicing and doubling, texture and color, arranging for varied ensembles, and professional score and parts preparation. The course emphasizes score study, idiomatic playability, listening, notation clarity, digital workflow, revision, and real-world rehearsal usability.',
  data = $orarjson${"slug": "orchestration-arranging", "title": "Orchestration / Arranging", "description": "This course develops practical and artistic skills in writing for instruments and ensembles. Students study ranges, transpositions, instrumental color, string, woodwind, brass, and percussion writing, full-orchestra scoring, voicing and doubling, texture and color, arranging for varied ensembles, and professional score and parts preparation. The course emphasizes score study, idiomatic playability, listening, notation clarity, digital workflow, revision, and real-world rehearsal usability.", "topics": [{"id": "ffb9b190-e857-4f83-9760-dfe3948caa2a", "type": "topic", "title": "Instrument Ranges and Transpositions", "description": "Orchestration begins with knowing what instruments can do, where they sound best, and how written pitch relates to sounding pitch. Students learn to write accurately before they write imaginatively.", "children": [{"id": "468c7740-0e64-4fe1-afa8-59535750ae00", "type": "subtopic", "title": "Practical ranges and registers", "children": [{"id": "8d6f2c16-25e3-4224-92e2-6124683a2ad9", "type": "concept", "title": "Written range"}, {"id": "94457171-a1d0-4c57-8189-466f016b7086", "type": "concept", "title": "Sounding range"}, {"id": "c4c4427d-c242-4b84-b2e8-a6d465863ce7", "type": "concept", "title": "Tessitura"}, {"id": "89656d75-ffcf-4f82-8942-ede875651493", "type": "concept", "title": "Extreme register risks"}, {"id": "e80cc723-afea-4fde-aef4-17fbd123eecd", "type": "concept", "title": "Register color"}], "description": "Why learn it: Students learn comfortable, effective, and extreme registers so parts are playable and expressive."}, {"id": "0c8d89b6-7aa5-4569-8d0e-e6ec98de9e17", "type": "subtopic", "title": "Transposing instruments", "children": [{"id": "28a4235c-532c-483b-9971-f268b544ed26", "type": "concept", "title": "B-flat instruments"}, {"id": "9109ef3f-cd6b-45ad-af79-fc76ee8ba56b", "type": "concept", "title": "E-flat instruments"}, {"id": "556da3fd-a430-4631-a4b2-7c260a1cd69c", "type": "concept", "title": "F horn"}, {"id": "077012bc-ee47-4a92-8b19-cbd577ef3c32", "type": "concept", "title": "Octave transpositions"}, {"id": "b9b5e66e-9d40-49b3-8248-f3686a9c43b5", "type": "concept", "title": "Concert vs. transposed score"}], "description": "Why learn it: Students practice reading, writing, and checking transpositions across orchestral and band instruments."}, {"id": "6b1ccb7f-3361-4a60-b5ae-f5e63909bcca", "type": "subtopic", "title": "Instrumental notation basics", "children": [{"id": "3692f28c-e57c-43ae-b209-d0f8172d5f58", "type": "concept", "title": "Clefs"}, {"id": "45016368-19cc-452a-ad05-17eb22349bcf", "type": "concept", "title": "Key signatures"}, {"id": "1452c9a3-0393-4808-b614-1cc2a033794a", "type": "concept", "title": "Octave signs"}, {"id": "09451cba-8812-4251-a21f-e43aecd3e411", "type": "concept", "title": "Instrument names"}, {"id": "5f13ec14-98d3-4825-a399-6435e777f169", "type": "concept", "title": "Part labels"}], "description": "Why learn it: Students learn notation conventions that prevent rehearsal confusion."}]}, {"id": "7a306bb5-426c-4967-b80b-f8472430f53d", "type": "topic", "title": "Score Study and Instrumental Listening", "description": "This added topic makes orchestration a listening discipline, not only a notation task. Students study master scores, recordings, and live demonstrations to connect page decisions to sound.", "children": [{"id": "d42dcd3c-bd03-4921-a675-399534d2e3c9", "type": "subtopic", "title": "Score-reading habits", "children": [{"id": "b783a398-0a83-43c7-8672-94d80d03356e", "type": "concept", "title": "Score order"}, {"id": "0b0d72e9-c27d-4d69-b990-0cfc604c6d0c", "type": "concept", "title": "Cueing entrances"}, {"id": "72dd1fdc-19b0-4698-9100-66107aa43a3c", "type": "concept", "title": "Condensed reading"}, {"id": "beaeb8da-0f0d-4f59-97d3-809f211e7d98", "type": "concept", "title": "Systems and rehearsal marks"}, {"id": "3bd71fcc-626a-41f8-917a-4064de90df58", "type": "concept", "title": "Score annotation"}], "description": "Why learn it: Students learn to follow full scores efficiently and locate orchestration decisions."}, {"id": "eb4673a0-8d71-4bcf-88fd-358d0a5cb1e2", "type": "subtopic", "title": "Timbre recognition", "children": [{"id": "cd08f0cd-ff10-40c5-8ab0-aa15f3716cd4", "type": "concept", "title": "Solo color"}, {"id": "86d55e27-e6b3-4d13-8c17-f5de611ad101", "type": "concept", "title": "Section sound"}, {"id": "f22b9401-03b2-4265-bf7a-bf7ab108060d", "type": "concept", "title": "Register shifts"}, {"id": "63b7c7b4-2a0a-41ad-866d-fc8c4ac4fa66", "type": "concept", "title": "Articulation color"}, {"id": "0166740b-9561-4c87-ab9f-62985d8d2a99", "type": "concept", "title": "Blend vs. contrast"}], "description": "Why learn it: Students build an aural vocabulary for instrumental color and blend."}, {"id": "b7a8016d-e9b5-4b42-a6e8-84899937f655", "type": "subtopic", "title": "Model analysis", "children": [{"id": "17d84c53-f851-42fe-b395-9d5069c6f67c", "type": "concept", "title": "Reduction"}, {"id": "d8bb96a8-333f-4187-9bce-16d27b6ad9ca", "type": "concept", "title": "Doubling map"}, {"id": "24542a6e-efe8-45d6-ac25-e320751b68c0", "type": "concept", "title": "Texture map"}, {"id": "533fe204-969b-44cc-b83d-0800b0872f7c", "type": "concept", "title": "Dynamic plan"}, {"id": "d870a30d-c21a-4ae3-8a01-682ce1d1282a", "type": "concept", "title": "Orchestration timeline"}], "description": "Why learn it: Students learn by reverse-engineering successful orchestral passages."}]}, {"id": "100e7e03-61a3-4a77-ab1d-8b4b1e57eaee", "type": "topic", "title": "String Writing", "description": "Strings are flexible, expressive, and central to many ensembles, but they require idiomatic knowledge. Students learn bowing, divisi, resonance, register, and texture.", "children": [{"id": "4733aae2-8e26-42de-8a65-4642b3fc7f37", "type": "subtopic", "title": "String technique and notation", "children": [{"id": "19bfe84a-99a1-4215-967e-975c1ef91b7f", "type": "concept", "title": "Bowing"}, {"id": "4c1b443e-7cc2-48b9-bf5e-319e938b7574", "type": "concept", "title": "Pizzicato"}, {"id": "5f9622d7-201b-4d00-878e-bd856be04879", "type": "concept", "title": "Double stops"}, {"id": "a46f6ac3-d03b-4164-9c8f-72fa7f0f6572", "type": "concept", "title": "Harmonics"}, {"id": "378f7a54-0684-472e-a431-245de96fdd97", "type": "concept", "title": "Divisi"}], "description": "Why learn it: Students learn the basic vocabulary that makes string parts playable."}, {"id": "39f05095-0258-4724-bc80-1f62ac151314", "type": "subtopic", "title": "Section writing", "children": [{"id": "f27bcf7f-128c-45dd-9838-7a116a0d5a26", "type": "concept", "title": "Violin I/II roles"}, {"id": "8a715e3a-839f-4514-858a-159a4aad31da", "type": "concept", "title": "Viola color"}, {"id": "3bd7fbf7-11f9-4f36-8918-87d6bafafe08", "type": "concept", "title": "Cello melody"}, {"id": "79644bb9-6132-445e-9bc9-4b0f1835d793", "type": "concept", "title": "Bass support"}, {"id": "34d22b31-852e-40d0-aaee-e52ec44cac05", "type": "concept", "title": "Spacing"}], "description": "Why learn it: Students learn to distribute melody, harmony, bass, and inner motion across the string choir."}, {"id": "9d938ea9-e7ad-4edb-b81e-6bbeecaa9cd4", "type": "subtopic", "title": "String textures", "children": [{"id": "556e660d-d751-4d48-ab57-71ab301cbb58", "type": "concept", "title": "Tremolo"}, {"id": "83f49fd2-b158-4eb1-b0e9-0d79edbcbbdb", "type": "concept", "title": "Ostinato"}, {"id": "34ae65d1-5e64-4480-963e-31d28ba59c7a", "type": "concept", "title": "Pads"}, {"id": "b98d6332-13e0-48e4-9c2a-115a4b9b4229", "type": "concept", "title": "Countermelody"}, {"id": "eab95836-b874-4e2c-b34b-b5ca6ba88675", "type": "concept", "title": "Chamber vs. orchestral writing"}], "description": "Why learn it: Students practice creating motion, weight, transparency, and intensity."}]}, {"id": "f1d6339e-11af-4f7c-bee8-10fe826429ec", "type": "topic", "title": "Woodwind Writing", "description": "Woodwinds offer vivid individuality, agility, blend, and color. Students learn to write lines that respect breath, register, finger technique, and timbral identity.", "children": [{"id": "724c229a-2d94-4256-8740-67102068d3b5", "type": "subtopic", "title": "Woodwind families and registers", "children": [{"id": "4c07badc-2ded-4f9d-bd9e-805d347d53da", "type": "concept", "title": "Flute and piccolo"}, {"id": "fd7a186f-c67c-45e7-bd8b-d249ba3c3691", "type": "concept", "title": "Oboe and English horn"}, {"id": "8db02dab-5ef4-4398-9c0f-879253e5ee8c", "type": "concept", "title": "Clarinet family"}, {"id": "f6cc30d7-dd9e-47f1-b7a1-0f6ab4d75c8a", "type": "concept", "title": "Bassoon and contrabassoon"}, {"id": "0f9a0903-9c37-4988-bc62-fbd2741d45ea", "type": "concept", "title": "Register breaks"}], "description": "Why learn it: Students learn characteristic colors and practical limits for flute, oboe, clarinet, bassoon, and auxiliaries."}, {"id": "28ca23ad-afd9-4e2f-b506-29775198a455", "type": "subtopic", "title": "Breath and line writing", "children": [{"id": "95ac6755-199c-4b89-9861-d38bfffe5ab1", "type": "concept", "title": "Breath marks"}, {"id": "1b0901c1-8cb8-4d98-92f8-8e721a10cbfc", "type": "concept", "title": "Rest placement"}, {"id": "877c1dc9-ef91-4cb9-b504-0f61bf659cff", "type": "concept", "title": "Sustained lines"}, {"id": "4dac1c9e-4b8c-4781-be94-05f23ea218f3", "type": "concept", "title": "Articulation"}, {"id": "b708cc86-9b86-4d6f-9460-d23cae8ea91b", "type": "concept", "title": "Technical passagework"}], "description": "Why learn it: Students learn to write wind parts that phrase naturally."}, {"id": "719e5e21-de92-4276-bdfe-fb79a0f3ae21", "type": "subtopic", "title": "Color combinations", "children": [{"id": "7fd26c24-f78f-4c14-8c60-5a6c449a51e5", "type": "concept", "title": "Unison color"}, {"id": "21e55bae-ae1a-4c49-92e8-b0cd16c43ec6", "type": "concept", "title": "Octave doubling"}, {"id": "162be389-7d09-4773-8437-a0eb88174561", "type": "concept", "title": "Choir writing"}, {"id": "8ac675fb-bcd2-4e09-969e-addd1c313826", "type": "concept", "title": "Solo handoffs"}, {"id": "b9961d60-e136-4a9b-96aa-2b1e7cdd4eef", "type": "concept", "title": "Mixed timbres"}], "description": "Why learn it: Students practice blending and contrasting woodwinds with each other and with other families."}]}, {"id": "d0903e32-e200-45f5-a9f1-c8b46119ca72", "type": "topic", "title": "Brass Writing", "description": "Brass writing carries power, brilliance, warmth, ceremony, and danger when mishandled. Students learn range, endurance, balance, mutes, articulation, and harmonic spacing.", "children": [{"id": "47fb3952-d52a-4afe-a953-d45d96606e6d", "type": "subtopic", "title": "Brass ranges and endurance", "children": [{"id": "a81ff563-a2c1-425a-93c1-df5bb74c795a", "type": "concept", "title": "Trumpet"}, {"id": "f0753155-16a3-4550-9d60-0efcc8c91976", "type": "concept", "title": "Horn"}, {"id": "6a95457b-126d-45a8-899f-ca18d2b1a91d", "type": "concept", "title": "Trombone"}, {"id": "240db8f2-f03f-4ce7-aa42-b19277cef94f", "type": "concept", "title": "Tuba"}, {"id": "d798b746-0068-4d65-aacb-508bf5da4376", "type": "concept", "title": "Fatigue management"}], "description": "Why learn it: Students learn how register, dynamics, rests, and repeated entries affect playability."}, {"id": "4b67b8e0-2a90-481f-830b-c1e8a5fa7548", "type": "subtopic", "title": "Brass choir voicing", "children": [{"id": "94eb993e-7cb4-45d5-bbb6-526d5913dd9a", "type": "concept", "title": "Open spacing"}, {"id": "449c7d0f-f010-44e6-a422-51d48c41f8bf", "type": "concept", "title": "Close spacing"}, {"id": "f5311f90-6899-4a94-9530-af6fcc325dea", "type": "concept", "title": "Horn middle voices"}, {"id": "9a9cfbac-0f79-472c-8c5b-05f728b1b74e", "type": "concept", "title": "Trombone chorales"}, {"id": "4a903fa3-00db-4cad-a505-7c09921ab7bd", "type": "concept", "title": "Bass support"}], "description": "Why learn it: Students practice spacing chords and distributing roles across the brass section."}, {"id": "e6c8e800-4a9a-4474-a087-82f033fb6442", "type": "subtopic", "title": "Color and articulation", "children": [{"id": "324cffa9-3b10-4d75-b903-8e066ee10bc1", "type": "concept", "title": "Mutes"}, {"id": "9358b946-b4d0-4d4a-b553-c05662a58fdd", "type": "concept", "title": "Marcato"}, {"id": "7590f3c1-ff78-4ad2-b49b-0be93d468f69", "type": "concept", "title": "Legato"}, {"id": "90ef8bdc-3430-41dd-8fc6-aa81ae6bd44d", "type": "concept", "title": "Fanfares"}, {"id": "eecc31a2-0303-48c1-a015-6bf030204b6b", "type": "concept", "title": "Soft brass writing"}], "description": "Why learn it: Students learn how brass color changes through mutes, attack, dynamics, and register."}]}, {"id": "89eb5622-68b0-4904-93ad-3fc7a92908f9", "type": "topic", "title": "Percussion", "description": "Percussion expands rhythm, color, emphasis, atmosphere, and theatricality. Students learn practical setup, notation, player logistics, and the difference between coloristic and structural percussion writing.", "children": [{"id": "d5c4ec8f-58e8-411b-8576-67ab409e8dea", "type": "subtopic", "title": "Pitched and unpitched percussion", "children": [{"id": "209eed2f-f0a3-4c03-9cd4-753348793ce8", "type": "concept", "title": "Timpani"}, {"id": "36941e87-24cf-4fdb-a8eb-d15615487735", "type": "concept", "title": "Mallet instruments"}, {"id": "76057292-94e5-42ff-84b3-7f9df95a6b03", "type": "concept", "title": "Drums"}, {"id": "0a3dc425-f1d5-436d-9819-cae5bdf6c58f", "type": "concept", "title": "Cymbals and gongs"}, {"id": "ebd42f0d-789b-4dcf-b24c-a505dba44d3a", "type": "concept", "title": "Accessory percussion"}], "description": "Why learn it: Students identify instruments, notation, and musical roles."}, {"id": "9d548f8d-0a5c-41cf-9d8c-408730ae6bff", "type": "subtopic", "title": "Logistics and setup", "children": [{"id": "1543865d-a57d-4d49-9485-e8d85e4679de", "type": "concept", "title": "Player count"}, {"id": "ebb22c06-b0f0-4e5e-aea3-e1d0b275e9df", "type": "concept", "title": "Instrument layout"}, {"id": "4ba41358-a95f-4495-85a4-cf827976b83c", "type": "concept", "title": "Mallet changes"}, {"id": "1bd072ef-b1ce-43c1-834a-ea6a20ac0d2b", "type": "concept", "title": "Page turns"}, {"id": "a8f70717-4112-4adf-9e1b-5c6e2c1ed9ed", "type": "concept", "title": "Setup time"}], "description": "Why learn it: Students learn to write parts that real players can execute with practical instrument changes."}, {"id": "68f0fe0b-6329-4016-bf28-2a255896b67b", "type": "subtopic", "title": "Percussion color and function", "children": [{"id": "3ac108c7-e5bc-4391-ac14-f83e8fc877c8", "type": "concept", "title": "Rhythmic drive"}, {"id": "c66d1ea1-f632-4f6c-8e21-d3d2e0cc96a0", "type": "concept", "title": "Impact points"}, {"id": "aa11e67e-bc96-4a92-a1b6-cb4441499f80", "type": "concept", "title": "Atmosphere"}, {"id": "eb381baa-1425-4ac7-b30b-645a10d33aed", "type": "concept", "title": "Transitions"}, {"id": "d4ba3e30-32ab-4778-9194-09321d7707eb", "type": "concept", "title": "Doubling gestures"}], "description": "Why learn it: Students learn how percussion supports rhythm, form, drama, and timbre."}]}, {"id": "a5832536-e012-47b4-9041-d152349324d7", "type": "topic", "title": "Scoring for Full Orchestra", "description": "Full-orchestra scoring requires long-range planning: balance, density, register, color, pacing, and rehearsal clarity. Students learn how to coordinate multiple families into a coherent sound.", "children": [{"id": "1cdee465-d88e-4c6e-8d73-7a6c6e9f01a8", "type": "subtopic", "title": "Orchestral balance", "children": [{"id": "1a493481-875c-4cd6-8cc2-07b64f1b9195", "type": "concept", "title": "Melody projection"}, {"id": "6701ace8-14e1-4b51-9438-9337d966e604", "type": "concept", "title": "Bass clarity"}, {"id": "dc66cd95-1a9a-4bdf-974c-3e9e59a11c32", "type": "concept", "title": "Accompaniment control"}, {"id": "97cca18c-39eb-4465-b452-e621e2515b33", "type": "concept", "title": "Register spacing"}, {"id": "da3becc0-9de1-476b-a63c-78221fad8717", "type": "concept", "title": "Dynamic realism"}], "description": "Why learn it: Students learn how register, dynamics, numbers of players, and instrumental projection affect audibility."}, {"id": "b3f79daf-7203-4c1d-b8a5-1e1dfc668a9c", "type": "subtopic", "title": "Family integration", "children": [{"id": "ea234688-6fad-408b-a07e-f936d3d057ca", "type": "concept", "title": "Layering"}, {"id": "00dbacbe-8c2e-4448-93e8-d77aa222489a", "type": "concept", "title": "Handoffs"}, {"id": "84801e21-9101-4112-a4b5-ee5aa9b30fa9", "type": "concept", "title": "Choir contrast"}, {"id": "5a7bada9-d1ce-4b50-8eba-668d1bcabe4b", "type": "concept", "title": "Tutti writing"}, {"id": "be832f27-5b6d-4d70-8c18-3dd8da4b58e0", "type": "concept", "title": "Transparent scoring"}], "description": "Why learn it: Students practice combining strings, winds, brass, and percussion without overcrowding."}, {"id": "cb3d9bad-b63d-4d5c-9ca6-14609d9fc3ea", "type": "subtopic", "title": "Large-scale orchestral pacing", "children": [{"id": "30734dbe-8e6d-4212-9d0d-0158fb36b00d", "type": "concept", "title": "Builds"}, {"id": "ac18250d-4a0f-40db-9e54-546a40297c70", "type": "concept", "title": "Thinning"}, {"id": "87d08e8b-e3b5-4e2b-ac7c-f61ff4a75012", "type": "concept", "title": "Climaxes"}, {"id": "cfb0ff81-8d98-4eb5-a7c2-29a6be620524", "type": "concept", "title": "Cadential color"}, {"id": "d22cf58e-2089-4302-b96e-9ee7164d3471", "type": "concept", "title": "Reorchestration of returns"}], "description": "Why learn it: Students learn how orchestration shapes form over time."}]}, {"id": "cda3acec-7dcc-4d29-886d-4f2c18adca25", "type": "topic", "title": "Voicing and Doubling", "description": "Voicing and doubling determine whether an arrangement sounds clear, muddy, powerful, thin, blended, or colorful. Students learn to control vertical spacing and instrumental reinforcement.", "children": [{"id": "698c63e0-2a75-40e3-9a6b-77aef409f9ea", "type": "subtopic", "title": "Chord spacing", "children": [{"id": "6bee240d-cf0b-4da6-9e37-ef84b0a640d7", "type": "concept", "titl